-- day it was paused and before the day it was resumed is skipped.
CREATE TABLE sheet_plan_pause (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id    BIGINT NOT NULL REFERENCES sheet_plan (id),
    paused_on  DATE NOT NULL,
    resumed_on DATE
);

